async function cargarAgua(files){FX=[];$('#fx').innerHTML='<div class="card">Leyendo facturas…</div>';
 try{await lector()}catch(e){$('#fx').innerHTML='<div class="card">No pude cargar el lector de PDF (la primera vez hace falta conexión a internet). Detalle: '+esc(e&&e.message||e)+'</div>';return}
 for(const f of files){try{const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;let t='';for(let i=1;i<=pdf.numPages;i++){const c=await(await pdf.getPage(i)).getTextContent();t+=c.items.map(x=>x.str).join(' ')+' '}FX.push({f:f.name,file:f,...leerFactura(t)})}catch(e){FX.push({f:f.name,err:1,msg:e&&e.message})}}
 verFX()}
function verFX(){const p=cur();if(!p||!$('#fx'))return;let n=0;
 const rows=FX.map(x=>{if(x.err||!x.pick||!x.cta||!x.tipo)return`<tr><td>${esc(x.f)}</td><td colspan="2" style="text-align:left;color:var(--bad)">No pude reconocer la factura. ¿Es un PDF con texto, no una foto?</td></tr>`;
 const T=TF[x.tipo],g=String(p[T.k]||'').replace(/\D/g,''),ok=!g||String(+g)==x.cta,mes=(x.pick.m-1+T.lag)%12;x.ok=ok;if(ok)n++;
 const av=!ok?`<br><small style="color:var(--bad)">No se carga: la cuenta de ${T.n.toLowerCase()} de esta propiedad es ${p[T.k]} y la factura es de la cuenta ${x.raw}</small>`:(mes!=S.m?`<br><small style="color:var(--warn)">Corresponde a la liquidación de ${MES[mes]}; estás cargando ${MES[S.m]}</small>`:'')+(!p.sv[x.tipo].on?`<br><small style="color:var(--warn)">${T.n} no está tildado para cobrar</small>`:(x.tipo=='luz'&&p.sv.luz.prop?`<br><small style="color:var(--warn)">La luz va por medidor (kW): este importe no se usa</small>`:''));
 return`<tr><td><b>${T.n}</b> · ${esc(x.f)}<br><small>Cuenta ${x.raw}${x.per?' · '+x.per:''}${g?'':' (se guardará en la ficha)'}</small></td><td>Vto ${x.pick.f}</td><td>${$$(x.pick.v)}${av}</td></tr>`}).join('');
 $('#fx').innerHTML=`<div style="border:1px solid var(--line);border-radius:8px;padding:10px;margin-bottom:10px;background:var(--soft)"><small>Facturas leídas (con varios vencimientos se toma el posterior al día ${S.corr.dAgua})</small><table class="t">${rows}</table><p class="ac"><button onclick="aplicarFX()" ${n?'':'disabled'}>Cargar en esta propiedad (${n})</button><button class="s" onclick="FX=[];$('#fx').innerHTML=''">Cancelar</button></p></div>`}
async function aplicarFX(){const p=cur(),k=ym(),fs=[];p.facturas=p.facturas||{};for(const x of FX)if(x.ok){p.sv[x.tipo].monto=x.pick.v;if(!p[TF[x.tipo].k])p[TF[x.tipo].k]=x.raw;(p.facturas[k]=p.facturas[k]||{})[x.tipo]=x.f;if(x.file)fs.push([x.tipo,x.file])}
 FX=[];FM=null;render();tot();for(const[t,fl]of fs){try{await idbDo('put','f:'+p.id+':'+k+':'+t,fl)}catch(e){alert('No pude guardar el PDF de la factura de '+t+' en el navegador, pero el importe quedó cargado.')}}}
let FM=null;const fmv=()=>FM||ym();
async function verFac(t){const p=cur(),key='f:'+p.id+':'+fmv()+':'+t;if(CV&&CV.key==key){URL.revokeObjectURL(CV.url);CV=null}else{const b=await idbDo('get',key);if(!b){alert('No encuentro el archivo en este navegador.');return}CV={id:p.id,key,url:URL.createObjectURL(b)}}render()}
async function quitarFac(t){if(!confirm('¿Quitar esta factura guardada?'))return;const p=cur(),m=fmv();await idbDo('del','f:'+p.id+':'+m+':'+t);delete p.facturas[m][t];CV=null;render()}
const hh=()=>document.documentElement.style.setProperty('--hh',document.querySelector('header').offsetHeight+'px');window.addEventListener('resize',hh);hh();if(S){render();tot();est();restaurarAdj()}
